bindings.state__template:
{% set inside = states('sensor.living_temp') | float(0) %}
{% set outside = states('sensor.outdoor_temp') | float(0) %}
{% if inside - outside > 5 %}
  {{ (inside - outside) | round(1) }}° warmer inside
{% elif inside < outside %}
  Colder inside
{% else %}
  About even
{% endif %}
